-- ============================================================
-- Migração 002 — importação dos dados do Organizze (export de 30/09/2026)
-- 6 contas, 57 categorias, 7084 lançamentos (dos quais 959 transferências entre contas).
-- ATENÇÃO: apaga primeiro TODOS os dados existentes do utilizador (contas, categorias e lançamentos).
-- Correr uma única vez no SQL Editor do Supabase, depois da migração 001.
-- ============================================================
do $$
declare uid uuid;
begin
  if (select count(*) from auth.users) <> 1 then
    raise exception 'Esperava exatamente 1 utilizador em auth.users; ajusta a linha "select id into uid" abaixo.';
  end if;
  select id into uid from auth.users order by created_at limit 1;

  delete from public.transactions where user_id = uid;
  delete from public.categories   where user_id = uid;
  delete from public.accounts     where user_id = uid;

  -- Contas

  -- Categorias (primeiro as principais, depois as sub-categorias)

  -- Lançamentos

  raise notice 'Importação concluída: % contas, % categorias, % lançamentos.', (select count(*) from public.accounts where user_id = uid), (select count(*) from public.categories where user_id = uid), (select count(*) from public.transactions where user_id = uid);
end $$;
